protected void initializeFromRebateDate(TAMRebateDate _rebateDate, FieldId _rebatePerFieldId, FieldId _periodTypeIdFieldId)
{
    next initializeFromRebateDate(_rebateDate, _rebatePerFieldId, _periodTypeIdFieldId);

    TAMRebateTable rebateTable = TAMRebateTable::find(_rebateDate.RebateId);
    vendorRebateTypeId = rebateTable.METVendRebateTypeId;

    TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);
    consolidationByRebateType = rebateDeal.METInvoiceConsolidationByRebateType;
}

protected container getRebateTransIdMapKey(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId)
{
    container con = next getRebateTransIdMapKey(_fromDate, _toDate, _rebateRefId);

    if (consolidationByRebateType)
    {
        return [_fromDate, _toDate, vendorRebateTypeId];
    }

    return con;
}
